:root {
  --color-primary: #1b5e3f;
  --color-primary-dark: #0d3a23;
  --color-accent: #f4a623;
  --color-accent-light: #ffd966;
  --color-accent-on-dark: #ffd966;
  --color-text: #1a1a1a;
  --color-text-light: #ffffff;
  --color-bg: #f9f9f9;
  --color-border: #e0e0e0;
  --color-error: #c1272d;
  --color-success: #27ae60;
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Verdana, sans-serif;
  --font-serif: Georgia, "Times New Roman", serif;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --spacing-2xl: 4rem;
  --radius: 0.375rem;
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.1);
  --shadow-md: 0 4px 6px rgba(0, 0, 0, 0.1);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  color: var(--color-text);
  background-color: var(--color-bg);
  line-height: 1.6;
}

h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: var(--spacing-md);
}

h1 {
  font-size: clamp(1.75rem, 5vw, 3rem);
}

h2 {
  font-size: clamp(1.5rem, 4vw, 2.5rem);
}

h3 {
  font-size: clamp(1.25rem, 3vw, 1.75rem);
}

p {
  margin-bottom: var(--spacing-md);
}

a {
  color: var(--color-primary-dark);
  text-decoration: none;
  transition: color 0.2s ease, background-color 0.2s ease;
}

a:hover {
  color: var(--color-accent);
}

a:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

header.site-header {
  background-color: var(--color-primary);
  padding: var(--spacing-md) 0;
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: var(--shadow-sm);
}

.logo {
  display: inline-block;
  font-family: "Trebuchet MS", Verdana, sans-serif;
  font-weight: 800;
  font-size: clamp(1.25rem, 4vw, 1.75rem);
  color: var(--color-text-light);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  text-shadow: 2px 2px 0 rgba(0, 0, 0, 0.3);
  transition: color 0.2s ease;
}

.logo:hover,
.logo:focus {
  color: var(--color-accent-light);
  outline: none;
}

.logo span {
  display: inline-block;
  margin-right: var(--spacing-xs);
  font-size: 1.3em;
}

footer.site-footer {
  background-color: var(--color-primary-dark);
  color: var(--color-text-light);
  padding: var(--spacing-xl) 0;
  margin-top: var(--spacing-2xl);
  text-align: center;
}

footer.site-footer a {
  color: var(--color-accent-on-dark);
}

footer.site-footer a:hover {
  text-decoration: underline;
}

footer.site-footer p {
  margin-bottom: var(--spacing-sm);
}

button,
input[type="submit"],
input[type="reset"],
input[type="button"] {
  display: inline-block;
  min-height: 44px;
  padding: 0.75rem 1.5rem;
  background-color: var(--color-primary-dark);
  color: var(--color-text-light);
  border: 2px solid var(--color-primary-dark);
  border-radius: var(--radius);
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s ease, border-color 0.2s ease, transform 0.1s ease;
}

button:hover,
input[type="submit"]:hover,
input[type="reset"]:hover,
input[type="button"]:hover {
  background-color: var(--color-accent);
  border-color: var(--color-accent);
  transform: translateY(-2px);
}

button:focus,
input[type="submit"]:focus,
input[type="reset"]:focus,
input[type="button"]:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

button:active,
input[type="submit"]:active,
input[type="reset"]:active,
input[type="button"]:active {
  transform: translateY(0);
}

label {
  display: block;
  margin-bottom: var(--spacing-xs);
  font-weight: 600;
  color: var(--color-text);
}

input[type="text"],
input[type="email"],
input[type="tel"],
input[type="number"],
input[type="date"],
input[type="select"],
select,
textarea {
  display: block;
  width: 100%;
  min-height: 44px;
  padding: 0.75rem;
  border: 2px solid var(--color-border);
  border-radius: var(--radius);
  font-family: var(--font-sans);
  font-size: 1rem;
  color: var(--color-text);
  background-color: var(--color-text-light);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="tel"]:focus,
input[type="number"]:focus,
input[type="date"]:focus,
input[type="select"]:focus,
select:focus,
textarea:focus {
  border-color: var(--color-primary-dark);
  outline: none;
  box-shadow: 0 0 0 3px rgba(27, 94, 63, 0.2);
}

textarea {
  min-height: 120px;
  resize: vertical;
}

.form-group {
  margin-bottom: var(--spacing-md);
}

.grid {
  display: grid;
  gap: var(--spacing-md);
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

.card {
  background-color: var(--color-text-light);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: var(--spacing-md);
  box-shadow: var(--shadow-sm);
  transition: box-shadow 0.2s ease, transform 0.2s ease;
}

.card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

section {
  padding: var(--spacing-xl) 0;
}

.hero {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
  color: var(--color-text-light);
  text-align: center;
  padding: var(--spacing-2xl) var(--spacing-md);
}

.hero h1 {
  color: var(--color-text-light);
  margin-bottom: var(--spacing-md);
}

.hero p {
  font-size: 1.125rem;
  margin-bottom: var(--spacing-lg);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.cta-button {
  display: inline-block;
  padding: 1rem 2rem;
  background-color: var(--color-accent);
  color: var(--color-primary-dark);
  border: none;
  border-radius: var(--radius);
  font-weight: 700;
  font-size: 1rem;
  cursor: pointer;
  transition: background-color 0.2s ease, transform 0.1s ease;
}

.cta-button:hover {
  background-color: var(--color-accent-light);
  transform: translateY(-2px);
}

.cta-button:focus {
  outline: 3px solid var(--color-text-light);
  outline-offset: 2px;
}

@media (max-width: 600px) {
  :root {
    --spacing-lg: 1.5rem;
    --spacing-xl: 2rem;
    --spacing-2xl: 2.5rem;
  }

  html {
    font-size: 14px;
  }

  .container {
    padding: 0 var(--spacing-sm);
  }

  .grid {
    grid-template-columns: 1fr;
  }

  section {
    padding: var(--spacing-lg) 0;
  }

  .hero {
    padding: var(--spacing-xl) var(--spacing-md);
  }

  h1 {
    font-size: 1.75rem;
  }

  h2 {
    font-size: 1.5rem;
  }

  h3 {
    font-size: 1.25rem;
  }
}

@media (min-width: 601px) {
  .grid {
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  }

  section {
    padding: var(--spacing-2xl) 0;
  }

  .hero {
    padding: var(--spacing-2xl) var(--spacing-md);
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

pages.css:
.camp-sessions .card p {
  margin-bottom: var(--spacing-sm);
}

.pricing-card {
  display: flex;
  flex-direction: column;
  position: relative;
}

.pricing-card--featured {
  border: 3px solid var(--color-accent);
  box-shadow: 0 8px 12px rgba(244, 166, 35, 0.2);
}

.price {
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-primary-dark);
  margin: var(--spacing-md) 0;
  display: flex;
  align-items: baseline;
  gap: 0.25rem;
}

.currency {
  font-size: 1.5rem;
}

.amount {
  font-size: 2.5rem;
}

.pricing-features {
  list-style: none;
  margin: var(--spacing-md) 0;
  flex-grow: 1;
}

.pricing-features li {
  padding: 0.5rem 0;
  color: var(--color-text);
}

.fine-print {
  font-size: 0.875rem;
  color: #666;
  font-style: italic;
  margin-top: auto;
}

.pricing-note {
  background-color: #f0f8f4;
  border-left: 4px solid var(--color-primary);
  padding: var(--spacing-lg);
  border-radius: var(--radius);
  margin-top: var(--spacing-2xl);
}

.pricing-includes {
  list-style: none;
  columns: 1;
}

.pricing-includes li {
  padding: 0.5rem 0;
  padding-left: 1.5rem;
  position: relative;
}

.pricing-includes li:before {
  content: "✓";
  position: absolute;
  left: 0;
  color: var(--color-primary-dark);
  font-weight: 700;
}

.registration-form {
  background-color: var(--color-text-light);
  padding: var(--spacing-lg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  max-width: 700px;
  margin: var(--spacing-xl) auto 0;
}

.form-fieldset {
  border: none;
  padding: 0 0 var(--spacing-lg) 0;
  margin-bottom: var(--spacing-lg);
  border-bottom: 2px solid var(--color-border);
}

.form-fieldset:last-of-type {
  border-bottom: none;
}

.form-legend {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-md);
  padding-bottom: var(--spacing-sm);
}

.checkbox-group {
  display: flex;
  align-items: flex-start;
  gap: var(--spacing-sm);
  margin-bottom: var(--spacing-md);
}

.checkbox-group input[type="checkbox"] {
  display: inline-block;
  width: auto;
  min-height: auto;
  min-width: 20px;
  min-height: 20px;
  margin-top: 0.5rem;
  cursor: pointer;
  flex-shrink: 0;
}

.checkbox-label {
  display: inline;
  margin-bottom: 0;
  font-weight: 400;
  cursor: pointer;
}

.form-submit {
  width: 100%;
  min-height: 50px;
  font-size: 1.125rem;
  font-weight: 700;
  background-color: var(--color-primary-dark);
  color: var(--color-text-light);
  border: 2px solid var(--color-primary-dark);
}

.form-submit:hover {
  background-color: var(--color-accent);
  border-color: var(--color-accent);
}

.form-note {
  font-size: 0.875rem;
  color: #666;
  margin-top: var(--spacing-sm);
  text-align: center;
}

.faq-item {
  margin-bottom: var(--spacing-lg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  overflow: hidden;
}

.faq-item summary {
  display: block;
  padding: var(--spacing-md);
  background-color: #f5f5f5;
  cursor: pointer;
  font-weight: 600;
  color: var(--color-primary-dark);
  user-select: none;
  transition: background-color 0.2s ease;
}

.faq-item summary:hover {
  background-color: #efefef;
}

.faq-item summary:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: -3px;
}

.faq-item[open] summary {
  background-color: #e8f4f0;
  border-bottom: 2px solid var(--color-primary);
}

.faq-item > p,
.faq-item > ul {
  padding: var(--spacing-md);
  margin: 0;
  border-top: 1px solid var(--color-border);
}

.faq-item ul {
  list-style-position: inside;
  padding-left: var(--spacing-lg);
}

.faq-item li {
  margin-bottom: 0.5rem;
}

.faq-item a {
  color: var(--color-primary-dark);
  text-decoration: underline;
}

@media (max-width: 600px) {
  .price {
    font-size: 2rem;
  }

  .amount {
    font-size: 2rem;
  }

  .pricing-note {
    padding: var(--spacing-md);
  }

  .registration-form {
    padding: var(--spacing-md);
  }

  .form-fieldset {
    padding-bottom: var(--spacing-md);
    margin-bottom: var(--spacing-md);
  }

  .form-legend {
    font-size: 1rem;
    margin-bottom: var(--spacing-sm);
  }

  .faq-item summary {
    padding: var(--spacing-md);
    font-size: 0.95rem;
  }

  .faq-item > p,
  .faq-item > ul {
    padding: var(--spacing-sm);
  }
}

@media (min-width: 601px) {
  .pricing-includes {
    columns: 2;
  }

  .pricing-includes li {
    break-inside: avoid;
  }
}

